use std::{fs,io::Write,path::Path};use serde_json::{Value,json};use sv_arbitro_comprobaciones::{huella,ciclo::{IDS,DOCS}};
type R<T>=Result<T,Box<dyn std::error::Error>>;fn ck(b:bool,s:&str)->R<()>{if b{Ok(())}else{Err(s.into())}}fn leer(p:&Path)->R<Value>{Ok(serde_json::from_slice(&fs::read(p)?)?)}fn save(p:&Path,b:&[u8])->R<()>{let mut f=fs::OpenOptions::new().write(true).create_new(true).open(p)?;f.write_all(b)?;f.sync_all()?;Ok(())}
fn main()->R<()>{let a=std::env::args().collect::<Vec<_>>();let r=Path::new(a.get(1).ok_or("Raíz")?);let base=Path::new(a.get(2).ok_or("Base inmutable")?);let p=r.join("preparacion");let plan=leer(&p.join("PLAN-CASOS.json"))?;let clave=leer(&p.join("REFERENCIA-EXTERNA.json"))?;let hipo=leer(&p.join("HIPOTESIS-PROPUESTA.json"))?;let old=leer(&base.join("despliegue/contraste/config/plan.json"))?;
ck(plan["casos"].as_array().map(Vec::len)==Some(7)&&clave["casos"].as_array().map(Vec::len)==Some(7),"Número de casos")?;ck(hipo["maximo_generaciones"]==7&&hipo["maximo_cargas"]==1,"Límite no fijado")?;
for i in 0..7 {let c=&plan["casos"][i];ck(c.as_object().map(|v|v.len())==Some(4)&&c["id"]==IDS[i]&&c["documento"]==DOCS[i]&&c["seccion"]=="S1"&&c["afirmacion"].as_str().is_some_and(|s|!s.is_empty()),"Identidad o campos del caso")?;ck(clave["casos"][i]["id"]==IDS[i],"Referencia ajena al caso")?;ck(matches!(clave["casos"][i]["decision"].as_str(),Some("RESPALDADA"|"CONTRADICHA"|"EVIDENCIA_INSUFICIENTE")),"Decisión de referencia ausente")?;}
for k in ["documento","seccion","afirmacion"]{ck(plan["casos"][0][k]==old["casos"][5][k],"Diagnóstico conocido alterado")?;}
let cat=leer(&base.join("despliegue/contraste/cache/catalogo.json"))?;let known=cat["documents"].as_array().unwrap().iter().find(|v|v["id"]=="N-C").ok_or("N-C")?.clone();ck(huella(known["sections"][0]["text"].as_str().unwrap().as_bytes())=="58de4de3939b7ba1b6e4d13bdaa41c23de310d7657ace72486e3ffa8e51d77f5","Original conocido distinto")?;
let mut docs=vec![known];for (id,title) in [("F-A","Norma sintética Velara sobre actas de verificación"),("F-B","Procedimiento sintético Talven para cámaras cerámicas"),("F-C","Expediente sintético Osera de observación y acceso")] {let text=fs::read_to_string(p.join("corpus").join(format!("{id}.txt")))?;let sha=huella(text.as_bytes());ck(text.chars().count()>2000&&text.chars().count()<=4000,"Documento no cabe exactamente en dos páginas")?;docs.push(json!({"id":id,"title":title,"url":"urn:sv:prueba-sintetica","retrieved_utc":"2026-10-02T00:00:00Z","updated_source":null,"synthetic":true,"raw_sha256":sha,"sections":[{"id":"S1","title":title,"sha256":sha,"text":text}]}));}
for (i,c) in clave["casos"].as_array().unwrap().iter().enumerate(){let doc=docs.iter().find(|d|d["id"]==DOCS[i]).unwrap();let t=doc["sections"][0]["text"].as_str().unwrap();for q in c["pasajes"].as_array().ok_or("Sin pasajes")?{ck(t.contains(q.as_str().ok_or("Pasaje no textual")?),"Pasaje externo ajeno al corpus")?;}}
let policy=fs::read(base.join("despliegue/contraste/config/politica.txt"))?;ck(huella(&policy)=="1adcc501f1b94aed756df0520ce551029e9cc742ed8db7a9f17fbd867b584bf3","Política cambiada")?;
let catalogo=serde_json::to_vec_pretty(&json!({"documents":docs,"version":cat["version"]}))?;let planbytes=serde_json::to_vec_pretty(&plan)?;let cr=r.join("despliegue/contraste");fs::create_dir_all(cr.join("cache"))?;fs::create_dir_all(cr.join("config"))?;
let fijacion=json!({"banco":"SG-ARBITRO-CONSISTENCIA-20261002-r1","estado":"fijado antes de inferencia; admisión técnica posterior requerida","catalogo_sha256":huella(&catalogo),"plan_sha256":huella(&planbytes),"politica_sha256":huella(&policy),"instruccion_sha256":huella(&fs::read(p.join("INSTRUCCION-PROPUESTA.txt"))?),"referencia_externa_sha256":huella(&fs::read(p.join("REFERENCIA-EXTERNA.json"))?),"hipotesis_sha256":huella(&fs::read(p.join("HIPOTESIS-PROPUESTA.json"))?),"maximo_generaciones":7,"maximo_cargas":1,"diagnostico_conocido":"D01: mismo corpus y afirmación N06; entrada cambia sólo por instrucción operativa","casos_nuevos":["F01","F02","F03","F04","F05","F06"],"clave_fuera_del_servidor":true,"detalle_documentos":docs.iter().map(|d|json!({"id":d["id"],"sha256":d["sections"][0]["sha256"],"caracteres":d["sections"][0]["text"].as_str().unwrap().chars().count(),"paginas":2})).collect::<Vec<_>>(),"autoria_licencia":clave["autoria_licencia"]});
save(&cr.join("cache/catalogo.json"),&catalogo)?;save(&cr.join("config/plan.json"),&planbytes)?;save(&cr.join("config/politica.txt"),&policy)?;save(&p.join("FIJACION-DEL-BANCO.json"),&serde_json::to_vec_pretty(&fijacion)?)?;println!("{fijacion}");Ok(())}